function validate(input) {
  for (const [index, values] of input.entries()) {
    const name = index === 0 ? 'quadTree1' : 'quadTree2';
    if (!Array.isArray(values) || values.length === 0) return `${name} needs at least its root.`;
    const isPair = (entry) => Array.isArray(entry) && entry.length === 2 && entry.every((bit) => bit === 0 || bit === 1);
    if (!isPair(values[0])) return `Each node of ${name} is [isLeaf, val] with 0s and 1s.`;
    // Walk the list as LeetCode reads it: every listed node owns the next four slots.
    const queue = [{ at: 0, level: 0 }];
    let next = 1;
    for (let q = 0; q < queue.length; q++) {
      const { at, level } = queue[q];
      const slots = [];
      for (let k = 0; k < 4; k++, next++) slots.push(next < values.length ? values[next] : null);
      if (values[at][0] === 1) {
        if (slots.some((slot) => slot !== null)) return `A leaf of ${name} must be followed by four nulls.`;
        continue;
      }
      if (!slots.every(isPair)) return `An internal node of ${name} needs four children, each [isLeaf, val].`;
      if (slots.every((slot) => slot[0] === 1 && slot[1] === slots[0][1])) return `In ${name}, four equal leaves must be written as one leaf.`;
      if (level + 1 > 9) return `${name} is at most 9 levels deep (n <= 2^9).`;
      for (let k = 0; k < 4; k++) queue.push({ at: next - 4 + k, level: level + 1 });
    }
    if (next < values.length) return `${name} has entries that belong to no node.`;
  }
  return null;
}

