function adapt(input, solve, kit) {
  const KEYS = ['topLeft', 'topRight', 'bottomLeft', 'bottomRight'];
  let limit = 0;
  // Rebuild a tree from its level-order list; every listed node owns the next four slots.
  const build = (values) => {
    const make = ([isLeaf, val]) => new kit.Node(val === 1, isLeaf === 1, null, null, null, null);
    const root = make(values[0]);
    const queue = [[root, 0]];
    let next = 1;
    for (let q = 0; q < queue.length; q++) {
      const [node, depth] = queue[q];
      limit = Math.max(limit, depth);
      if (node.isLeaf) {
        next += 4;
        continue;
      }
      for (const key of KEYS) {
        node[key] = make(values[next++]);
        queue.push([node[key], depth + 1]);
      }
    }
    return root;
  };
  const result = solve(build(input[0]), build(input[1]));
  // Write the answer back in the same form; internal values are free, so they are shown as 0.
  const out = [];
  const queue = [[result, 0]];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) {
      out.push(null);
      continue;
    }
    const [node, depth] = queue[q];
    if (!node || typeof node !== 'object') throw new Error('Return a quad-tree node; every internal node needs four child nodes.');
    if (depth > limit) throw new Error('The returned tree is deeper than either input, so it is not a valid quad-tree of the grid.');
    if (node.isLeaf === true || node.isLeaf === 1) {
      if (![true, false, 0, 1].includes(node.val)) throw new Error('A leaf needs val true or false.');
      out.push([1, Number(node.val)]);
      queue.push(null, null, null, null);
    } else {
      out.push([0, 0]);
      for (const key of KEYS) queue.push([node[key], depth + 1]);
    }
  }
  while (out.length > 0 && out[out.length - 1] === null) out.pop();
  return out;
}

