function intersect(quadTree1, quadTree2) {
  // Paint both trees onto one grid (painting a 1 twice is still 1), then rebuild the tree from the grid.
  const height = (node) => node.isLeaf ? 0 : 1 + Math.max(height(node.topLeft), height(node.topRight), height(node.bottomLeft), height(node.bottomRight));
  const n = 2 ** Math.max(height(quadTree1), height(quadTree2));
  const grid = Array.from({ length: n }, () => new Array(n).fill(0));
  const paint = (node, r, c, size) => {
    if (node.isLeaf) {
      if (node.val) for (let i = r; i < r + size; i++) for (let j = c; j < c + size; j++) grid[i][j] = 1;
      return;
    }
    const h = size / 2;
    paint(node.topLeft, r, c, h); paint(node.topRight, r, c + h, h);
    paint(node.bottomLeft, r + h, c, h); paint(node.bottomRight, r + h, c + h, h);
  };
  paint(quadTree1, 0, 0, n);
  paint(quadTree2, 0, 0, n);
  const make = (r, c, size) => {
    let ones = 0;
    for (let i = r; i < r + size; i++) for (let j = c; j < c + size; j++) ones += grid[i][j];
    if (ones === 0 || ones === size * size) return new _Node(ones > 0, true, null, null, null, null);
    const h = size / 2;
    return new _Node(true, false, make(r, c, h), make(r, c + h, h), make(r + h, c, h), make(r + h, c + h, h));
  };
  return make(0, 0, n);
}

