function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  const large = size === 'large';
  const maxDepth = large ? 9 : rand() < 0.1 ? 0 : 1 + pick(3);
  const target = large ? 60 + pick(50) : 1 + pick(6);
  const leaf = (val, depth) => ({ leaf: true, val, depth, kids: null });
  // Split randomly chosen leaves (above the depth limit) into four random leaves.
  const grow = (root, splits, bias) => {
    for (let s = 0; s < splits; s++) {
      const leaves = [];
      const collect = (node) => {
        if (!node.leaf) node.kids.forEach(collect);
        else if (node.depth < maxDepth) leaves.push(node);
      };
      collect(root);
      if (leaves.length === 0) break;
      const chosen = leaves[pick(leaves.length)];
      chosen.leaf = false;
      chosen.val = pick(2);
      chosen.kids = Array.from({ length: 4 }, () => leaf(rand() < bias ? 1 : 0, chosen.depth + 1));
    }
    return root;
  };
  // Merge four equal leaves into one, bottom-up, so the tree follows the quad-tree rule.
  const simplify = (node) => {
    if (node.leaf) return node;
    node.kids = node.kids.map(simplify);
    if (node.kids.every((kid) => kid.leaf && kid.val === node.kids[0].val)) return leaf(node.kids[0].val, node.depth);
    return node;
  };
  const flip = (node) => node.leaf ? leaf(1 - node.val, node.depth) : { leaf: false, val: pick(2), depth: node.depth, kids: node.kids.map(flip) };
  const serialize = (root) => {
    const out = [];
    const queue = [root];
    for (let i = 0; i < queue.length; i++) {
      const node = queue[i];
      if (node === null) out.push(null);
      else {
        out.push([node.leaf ? 1 : 0, node.val]);
        queue.push(...(node.leaf ? [null, null, null, null] : node.kids));
      }
    }
    while (out.length > 0 && out[out.length - 1] === null) out.pop();
    return out;
  };
  const first = simplify(grow(leaf(pick(2), 0), target, rand()));
  // Mostly independent trees, sometimes a near or exact complement (so quarters merge), sometimes a single leaf.
  const style = rand();
  let second;
  if (style < 0.45) second = simplify(grow(leaf(pick(2), 0), target, rand()));
  else if (style < 0.75) second = simplify(grow(flip(first), large ? 1 + pick(10) : 1 + pick(3), rand()));
  else if (style < 0.9) second = leaf(pick(2), 0);
  else second = flip(first);
  const pairOfTrees = [serialize(first), serialize(second)];
  return rand() < 0.5 ? pairOfTrees : pairOfTrees.reverse();
}
